add_action('wp_footer', function () {
?>
    <script>
        (function() {

            // Đã có cookie thì không xử lý nữa
            if (document.cookie.includes('googtrans=')) {
                return;
            }

            // Ngôn ngữ trình duyệt
            let lang = (navigator.language || navigator.userLanguage || 'en')
                .toLowerCase()
                .split('-')[0];

            // Danh sách ngôn ngữ đã bật trong GTranslate
            const supported = [
                'vi', 'en', 'ja', 'ko', 'zh', 'fr', 'de', 'es', 'it', 'pt',
                'ru', 'ar', 'th', 'id', 'ms', 'hi', 'nl', 'pl', 'tr',
                'cs', 'da', 'fi', 'el', 'he', 'hu', 'no', 'ro', 'sv', 'uk'
            ];

            if (supported.includes(lang)) {
                document.cookie = `googtrans=/en/${lang}; path=/`;
                location.reload();
            }

        })();
    </script>
<?php
});

add_filter('login_redirect', function ($redirect_to, $requested_redirect_to, $user) {

    if (!empty($user) && !is_wp_error($user)) {
        return home_url('/maps/');
    }

    return $redirect_to;

}, 999, 3);

add_action('rest_api_init', function () {

    register_rest_route('enishi/v1', '/livekit-token', [
        'methods' => 'GET',
        'permission_callback' => '__return_true',
        'callback' => function ($request) {

            $room = sanitize_text_field(
                $request->get_param('room')
            );

            $user = wp_get_current_user();

            return [
                'url' => 'wss://live.pt-solution.vn',
                'token' => enishi_generate_livekit_token(
                    $room,
                    (string)$user->ID
                )
            ];
        }
    ]);

});

function enishi_generate_livekit_token($room, $identity)
{
    $apiKey = 'ENISHI';
    $apiSecret = 'd8f8d3f9a2f4a3c8e7b1d5f6a9c2e4b7d1f8c3a6e9b2f5d7a4c1e8f6b3d9a2';

    $header = [
        'alg' => 'HS256',
        'typ' => 'JWT'
    ];

    $payload = [
        'iss' => $apiKey,
        'sub' => $identity,
        'nbf' => time(),
        'exp' => time() + 3600,
        'video' => [
            'roomJoin'     => true,
            'room'         => $room,
            'canPublish'   => true,
            'canSubscribe' => true
        ]
    ];

    $headerEncoded = rtrim(
        strtr(base64_encode(json_encode($header)), '+/', '-_'),
        '='
    );

    $payloadEncoded = rtrim(
        strtr(base64_encode(json_encode($payload)), '+/', '-_'),
        '='
    );

    $signature = hash_hmac(
        'sha256',
        $headerEncoded . '.' . $payloadEncoded,
        $apiSecret,
        true
    );

    $signatureEncoded = rtrim(
        strtr(base64_encode($signature), '+/', '-_'),
        '='
    );

    return $headerEncoded . '.' . $payloadEncoded . '.' . $signatureEncoded;
}